def _mainland(x):
    """A Taiwan-form drawing with each Taiwan-only part (_TW_PARTS) put back to
    the mainland's: what a shared character's ZHS form (the end of this file)
    and a Simplified character built on a Traditional one draw."""
    for tw, cn in _TW_PARTS:
        if tw in K and x is K[tw]:
            return K[cn]
    if isinstance(x, tuple) and x and x[0] == 'box':
        return ('box', [(_mainland(p), r) for p, r in x[1]])
    if isinstance(x, tuple) and x and x[0] in ('lr', 'tb'):
        return (x[0], _mainland(x[1]), _mainland(x[2]), x[3])
    return x


