# Taiwan's 4,808 or the mainland's level 1. 蘭亭集序: 禊 暎 俛. 前赤壁賦: 蜉 蝣.
# 滕王閣序: 軫 棨 襜 驂 騑 闥 甍 紆 舸 舳 鶩 遄 睢 鄴 睇 眄 溟 閽 愨 笏 滕.
