# Mainland China sets the full-width marks in the left of the box, and
# 。，、 in its lower left (GB/T 15834); Taiwan centres them. The fonts take
# Taiwan's by default and these where text is tagged Simplified Chinese
# (OpenType locl, language ZHS).
def _moved(strokes, dx, dy):
    from skeleton import transform
    return [(k, transform(d, lambda p: (p[0] + dx, p[1] + dy))) for k, d in strokes]


def _narrow_zou(x, scale=1.0):
    """x with each 辶 drawn at under 3/4 width swapped for its wider 辶N."""
    if scale < 0.76:
        for full, narrow in (('辶T', '辶TN'), ('辶', '辶N')):
            if x is K[full]:
                return K[narrow]
    if isinstance(x, tuple) and x and x[0] == 'box':
        parts = [(_narrow_zou(p, scale * (r[2] - r[0]) / 1000), r) for p, r in x[1]]
        if any(q is not p for (q, _), (p, _) in zip(parts, x[1])):
            return ('box', parts)
    elif isinstance(x, tuple) and x and x[0] in ('lr', 'tb'):
        a, b = _narrow_zou(x[1], scale), _narrow_zou(x[2], scale)
        if a is not x[1] or b is not x[2]:
            return (x[0], a, b, x[3])
    return x       # unchanged parts stay the same objects, for _mainland to know them


for _ch in C:
    C[_ch] = _narrow_zou(C[_ch])


ZHS = {ch: _moved(C[ch], dx, dy) for ch, dx, dy in (
    ('。', -270, 300), ('，', -270, 260), ('、', -260, 280),
    ('；', -280, 0), ('：', -280, 0), ('？', -270, 0), ('！', -280, 0))}

